use std::io::*;

fn eval(line: &str) -> String {
    let mut st: Vec<i64> = Vec::new();
    for t in line.split_whitespace() {
        let b = t.as_bytes();
        if t.len() == 1 && b"+-*/".contains(&b[0]) {
            if st.len() < 2 {
                return "error: underflow".into();
            }
            let y = st.pop().unwrap();
            let x = st.pop().unwrap();
            let r = match b[0] {
                b'+' => x.wrapping_add(y),
                b'-' => x.wrapping_sub(y),
                b'*' => x.wrapping_mul(y),
                _ => {
                    if y == 0 {
                        return "error: divzero".into();
                    }
                    x.wrapping_div(y)
                }
            };
            st.push(r);
        } else {
            let d = if b[0] == b'-' { &b[1..] } else { b };
            if d.is_empty() || !d.iter().all(|c| c.is_ascii_digit()) {
                return "error: token".into();
            }
            match t.parse::<i64>() {
                Ok(v) => st.push(v),
                Err(_) => return "error: token".into(),
            }
        }
    }
    if st.len() != 1 {
        "error: leftover".into()
    } else {
        st[0].to_string()
    }
}

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    for l in s.lines() {
        if l.trim().is_empty() {
            continue;
        }
        println!("{}", eval(l));
    }
}

